import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-01-18","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-01-18","date":"2022-01-18T00:00:00.000Z","updated":"2022-01-19T00:00:00.000Z","tags":["Ceph","Orchestrator","Quincy 版本","回溯策略","Pacific 版本","Surf Loop","数据一致性","线程管理","超时机制","团队变动"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-01-18.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-01-18.md","lastUpdated":1780459816000}'),i={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-01-18.md"};function n(l,t,s,c,g,h){return r(),e("div",null,[...t[0]||(t[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>Quincy 版本发布</strong>: Quincy 版本即将发布，但并非迫在眉睫。团队需要确保对 Quincy 的回溯工作得到妥善处理，特别是对于每个 bug 修复和功能更新。</li><li><strong>回溯策略</strong>: 会议讨论了回溯工作的策略，决定采用批量回溯以减少额外工作量和冲突。</li><li><strong>Pacific 版本的回溯</strong>: 针对 Pacific 版本的回溯工作仍在进行中，特别是需要将 agent 回溯到 Pacific，团队需要尽快解决剩余的两个问题。</li><li><strong>Surf Loop 中的竞争条件</strong>: 讨论了 Surf Loop 中存在的竞争条件，特别是在不同线程中修改数据结构时可能引发的问题。</li><li><strong>Agent 和数据一致性</strong>: 讨论了如何通过 agent 和 metadata up-to-date flag 来解决数据一致性问题。</li><li><strong>线程和超时问题</strong>: 讨论了线程管理和超时问题，特别是在执行 SSH 命令时可能出现的挂起问题。</li><li><strong>团队变动</strong>: Sebastian 宣布他将在一月底离开 Red Hat，这将是他参与的倒数第二次会议。</li></ul><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>回溯策略</strong>: 采用批量回溯策略，避免单独回溯带来的额外工作量和冲突。</li><li><strong>Pacific 版本的回溯</strong>: 尽快解决剩余的两个问题，并加速完成对 Pacific 版本的回溯工作。</li><li><strong>Surf Loop 中的竞争条件</strong>: 进一步调查和解决 Surf Loop 中的竞争条件。</li><li><strong>Agent 和数据一致性</strong>: 通过 agent 和 metadata up-to-date flag 来解决数据一致性问题。</li><li><strong>线程和超时问题</strong>: 引入超时机制和健康警告，以解决执行 SSH 命令时可能出现的挂起问题。</li><li><strong>团队变动</strong>: 确认 Adam 将接手 Orchestrator 每周会议的主持工作。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>Quincy 版本的回溯</strong>: 确保对 Quincy 的回溯工作得到妥善处理。</li><li><strong>Pacific 版本的回溯</strong>: 解决剩余的两个问题，并加速完成对 Pacific 版本的回溯工作。</li><li><strong>Surf Loop 中的竞争条件</strong>: 进一步调查和解决 Surf Loop 中的竞争条件。</li><li><strong>Agent 和数据一致性</strong>: 实施通过 agent 和 metadata up-to-date flag 来解决数据一致性的方案。</li><li><strong>线程和超时问题</strong>: 引入超时机制和健康警告，以解决执行 SSH 命令时可能出现的挂起问题。</li><li><strong>团队变动</strong>: 确认 Adam 将接手 Orchestrator 每周会议的主持工作。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li><strong>Docker 镜像缓存</strong>: 讨论了 Docker 镜像缓存的问题，特别是关于 upstream CI 的镜像缓存和 OpenStack 团队的需求。</li></ul><h3 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h3><ul><li>会议在确认了各项议题的后续行动计划后结束，团队成员预祝大家有一个愉快的周末。</li></ul>',11)])])}const p=a(i,[["render",n]]);export{d as __pageData,p as default};
